const p = $input.first().json;
const errors = [];
const op = p.operation;
if (!['update', 'delete'].includes(op)) errors.push('operation phai la update hoac delete');
if (!p.user_id) errors.push('thieu user_id');
if (!p.target_event_id && !p.target_title) errors.push('thieu target_event_id hoac target_title');
if (p.target_date && !/^\d{4}-\d{2}-\d{2}$/.test(String(p.target_date))) errors.push('target_date phai dang YYYY-MM-DD');

const OFFSET = 7 * 3600000;
const toLocal = (v) => {
  if (v === undefined || v === null || v === '') return null;
  const s = String(v);
  const hasTz = /(Z|[+-]\d{2}:?\d{2})$/.test(s);
  const ms = new Date(hasTz ? s : s.replace(' ', 'T') + '+07:00').getTime();
  if (Number.isNaN(ms)) { errors.push('Thoi gian khong hop le: ' + s); return null; }
  return new Date(ms + OFFSET).toISOString().slice(0, 19).replace('T', ' ');
};
let updates = null;
if (op === 'update') {
  const u = p.updates || {};
  updates = {
    title: u.title ? String(u.title).trim() : null,
    location: u.location ? String(u.location).trim() : null,
    start_time: toLocal(u.start_time),
    end_time: toLocal(u.end_time)
  };
  if (!updates.title && !updates.location && !updates.start_time && !updates.end_time) errors.push('updates khong co truong nao can sua');
  if (updates.start_time && updates.end_time && updates.end_time <= updates.start_time) errors.push('end_time phai sau start_time');
}
if (errors.length) return [{ json: { valid: false, response: { status: 'error', error_code: 'INVALID_INPUT', message: errors.join('; ') } } }];

return [{ json: {
  valid: true,
  operation: 'find_event',
  data: {
    google_event_id: p.target_event_id || null,
    external_user_id: String(p.user_id),
    title_like: p.target_event_id ? null : p.target_title,
    on_date: p.target_event_id ? null : (p.target_date || null)
  },
  op, user_id: String(p.user_id), target_event_id: p.target_event_id || null,
  allow_unmanaged: p.allow_unmanaged === true, updates
} }];

const ctx = $('Validate Input').first().json;
const r = $input.first().json;
if (!r.success) return [{ json: { resolved: false, response: { status: 'error', error_code: 'DB_ERROR', message: 'Khong tra cuu duoc su kien: ' + (r.error || '') } } }];
const rows = r.rows;
const verb = ctx.op === 'delete' ? 'xoa' : 'sua';
if (rows.length === 0) {
  if (ctx.allow_unmanaged && ctx.target_event_id) return [{ json: { resolved: true, event: { google_event_id: ctx.target_event_id, unmanaged: true } } }];
  return [{ json: { resolved: false, response: { status: 'target_not_found', message: 'Khong tim thay su kien can ' + verb + '.' } } }];
}
if (rows.length > 1) {
  return [{ json: { resolved: false, response: {
    status: 'target_ambiguous',
    message: 'Co ' + rows.length + ' su kien phu hop; hay gui target_event_id cu the.',
    candidates: rows.map((x) => ({ google_event_id: x.google_event_id, title: x.title, start_time: x.start_time, end_time: x.end_time }))
  } } }];
}
return [{ json: { resolved: true, event: { ...rows[0], unmanaged: false } } }];

const res = $input.first().json;
const code = res.statusCode;
if ([200, 204, 404, 410].includes(code)) return [{ json: { gcal_ok: true } }]; // 404/410: da bi xoa tren Google => coi nhu thanh cong
const detail = code ? 'HTTP ' + code : (typeof res.error === 'string' ? res.error : (res.error && res.error.message) || 'khong ro');
return [{ json: { gcal_ok: false, response: { status: 'error', error_code: 'GCAL_DELETE_FAILED', message: 'Khong xoa duoc lich tren Google Calendar (' + detail + ').' } } }];

const ev = $('Resolve Target').first().json.event;
const r = $input.first().json;
const warnings = [];
if (!r.success) warnings.push({ code: 'DB_SYNC_FAILED', message: 'Da xoa tren Google Calendar nhung chua cap nhat CSDL: ' + (r.error || '') });
return [{ json: { response: { status: 'deleted', google_event_id: ev.google_event_id, title: ev.title || null, unmanaged: !!ev.unmanaged, warnings } } }];

const ctx = $('Validate Input').first().json;
const ev = $input.first().json.event;
const u = ctx.updates;
const OFFSET = 7 * 3600000;
const toMs = (s) => new Date(String(s).replace(' ', 'T') + '+07:00').getTime();
const toLocal = (ms) => new Date(ms + OFFSET).toISOString().slice(0, 19).replace('T', ' ');
const toIso = (s) => String(s).replace(' ', 'T') + '+07:00';

const fin = { title: u.title, location: u.location, start_time: u.start_time, end_time: u.end_time };
// Chi doi gio bat dau => giu nguyen thoi luong cu (neu biet)
if (fin.start_time && !fin.end_time && ev.start_time && ev.end_time) {
  fin.end_time = toLocal(toMs(fin.start_time) + (toMs(ev.end_time) - toMs(ev.start_time)));
}
const body = {};
if (fin.title) body.summary = fin.title;
if (fin.location) body.location = fin.location;
if (fin.start_time) body.start = { dateTime: toIso(fin.start_time), timeZone: 'Asia/Ho_Chi_Minh' };
if (fin.end_time) body.end = { dateTime: toIso(fin.end_time), timeZone: 'Asia/Ho_Chi_Minh' };
return [{ json: {
  gcal_url: 'https://www.googleapis.com/calendar/v3/calendars/primary/events/' + encodeURIComponent(ev.google_event_id),
  gcal_body: body, final: fin
} }];

const res = $input.first().json;
const code = res.statusCode;
if (code === 200) return [{ json: { gcal_ok: true } }];
if (code === 404 || code === 410) return [{ json: { gcal_ok: false, response: { status: 'target_not_found', message: 'Su kien khong con ton tai tren Google Calendar.' } } }];
const detail = code ? 'HTTP ' + code : (typeof res.error === 'string' ? res.error : (res.error && res.error.message) || 'khong ro');
return [{ json: { gcal_ok: false, response: { status: 'error', error_code: 'GCAL_UPDATE_FAILED', message: 'Khong sua duoc lich tren Google Calendar (' + detail + ').' } } }];

const ev = $('Resolve Target').first().json.event;
const f = $('Prep GCal Update').first().json.final;
return [{ json: { operation: 'update_event', data: { google_event_id: ev.google_event_id, title: f.title, location: f.location, start_time: f.start_time, end_time: f.end_time } } }];

const ev = $('Resolve Target').first().json.event;
const f = $('Prep GCal Update').first().json.final;
const r = $input.first().json;
const warnings = [];
if (!r.success) warnings.push({ code: 'DB_SYNC_FAILED', message: 'Da sua tren Google Calendar nhung chua dong bo CSDL: ' + (r.error || '') });
const row = r.success && r.rows[0] ? r.rows[0] : null;
return [{ json: { response: {
  status: 'updated',
  event: {
    google_event_id: ev.google_event_id,
    title: row ? row.title : (f.title || ev.title || null),
    location: row ? row.location : (f.location || ev.location || null),
    start_time: row ? row.start_time : (f.start_time || ev.start_time || null),
    end_time: row ? row.end_time : (f.end_time || ev.end_time || null)
  },
  warnings
} } }];
